import{_ as e,o,c as i,a0 as s}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Rullst Studio: Real-Time Monitoring","description":"","frontmatter":{},"headers":[],"relativePath":"guide/3-rullst-studio.md","filePath":"guide/3-rullst-studio.md"}'),a={name:"guide/3-rullst-studio.md"};function l(r,t,n,u,d,c){return o(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="rullst-studio-real-time-monitoring" tabindex="-1">Rullst Studio: Real-Time Monitoring <a class="header-anchor" href="#rullst-studio-real-time-monitoring" aria-label="Permalink to &quot;Rullst Studio: Real-Time Monitoring&quot;">​</a></h1><p><strong>Rullst Studio</strong> is your development control room. It comes built-in with all Rullst Blueprints.</p><p>While you develop your application on port <code>3000</code>, Rullst Studio automatically boots up on port <code>5555</code>.</p><h2 id="what-is-rullst-studio" tabindex="-1">What is Rullst Studio? <a class="header-anchor" href="#what-is-rullst-studio" aria-label="Permalink to &quot;What is Rullst Studio?&quot;">​</a></h2><p>The Studio acts as a local observability dashboard. It connects to your Rullst application via WebSockets in the background to capture runtime telemetry without affecting your app&#39;s performance.</p><p>With the Studio, you can:</p><ul><li><strong>Monitor Traffic:</strong> See HTTP requests, response times, and status codes in real-time.</li><li><strong>Audit SQL Queries:</strong> Observe every query generated by <code>rullst-orm</code>, including execution time and bindings. This is vital for hunting down N+1 query bottlenecks.</li><li><strong>Analyze Logs:</strong> View the unified output of structured <code>tracing</code> without standard console pollution.</li><li><strong>Debug Async Jobs:</strong> Visualize the worker queue and identify failing jobs.</li></ul><h2 id="how-to-access" tabindex="-1">How to Access <a class="header-anchor" href="#how-to-access" aria-label="Permalink to &quot;How to Access&quot;">​</a></h2><ol><li>Run your Rullst project:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rullst</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div></li><li>Open your browser at <code>http://localhost:5555</code></li></ol><blockquote><p><strong>Note:</strong> Rullst Studio was designed exclusively for local development environments (<code>cargo rullst dev</code>). In production (compiled via <code>cargo build --release</code>), Studio&#39;s features are completely stripped away via conditional compilation (<code>cfg(debug_assertions)</code>), guaranteeing <strong>Zero Overhead</strong> for your server.</p></blockquote>',10)])])}const g=e(a,[["render",l]]);export{h as __pageData,g as default};
